  $prscjson${"slug": "public-relations-strategic-communication", "title": "Public Relations / Strategic Communication", "description": "This course prepares students to plan, write, execute, evaluate, and defend ethical public relations and strategic communication programs. Students learn PR history and theory, RPIE planning, stakeholder research, media relations, professional writing, PESO integration, digital and social strategy, reputation, CSR, issues management, crisis response, internal communication, global contexts, ethics, law, accessibility, AI, measurement, and campaign portfolio development.", "topics": [{"id": "823a8f70-80e8-4634-bc9f-5e2487716fc2", "type": "topic", "title": "Public Relations and Strategic Communication Foundations", "description": "Students learn PR as relationship-centered, research-based communication for organizations, publics, issues, and society.", "children": [{"id": "5ec59cea-632a-4868-bdee-4c4fb628b240", "type": "subtopic", "title": "PR as relationship work", "children": [{"id": "82a22bf8-72d7-4918-8bd9-ceb021d1720a", "type": "concept", "title": "Organizations, publics, stakeholders, and communities"}, {"id": "033a6d34-2857-417b-b28a-18865ce521b4", "type": "concept", "title": "Mutual understanding, legitimacy, and trust"}, {"id": "27a02257-4b00-4c9d-a97e-32e9e8788be5", "type": "concept", "title": "Relationship quality and long-term reputation"}], "description": "The point is to understand PR as ongoing relationship-building, not only publicity."}, {"id": "a9136fa5-f66f-4ef4-892e-b2b1abc1d79d", "type": "subtopic", "title": "Strategic communication", "children": [{"id": "e0e1dee2-a5c8-4d0e-a9e3-1c0029da6cfc", "type": "concept", "title": "Objectives, strategy, tactics, and outcomes"}, {"id": "4a78aada-a7c6-4c43-a97e-f2eb1db72f85", "type": "concept", "title": "Communication as management function"}, {"id": "bd659385-3eda-4a35-96bf-82796e7e7f61", "type": "concept", "title": "Counsel, advocacy, and public responsibility"}], "description": "Students learn how communication supports organizational and public-interest goals."}, {"id": "28a4def9-5b3b-4d6f-bcda-6a79a637e31a", "type": "subtopic", "title": "Professional scope", "children": [{"id": "2ea2392a-a21e-4f26-81c5-d838ff1bdb62", "type": "concept", "title": "Agency, in-house, nonprofit, government, and consulting settings"}, {"id": "db6641ea-1059-4151-a9d6-64b789a4e5fd", "type": "concept", "title": "PR, strategic communication, public affairs, and corporate communication"}, {"id": "1da6607b-68e8-445d-8b3d-9e5f4922bd17", "type": "concept", "title": "Portfolio expectations and career pathways"}], "description": "PR work spans writing, planning, counseling, media, digital, internal, crisis, and measurement roles."}]}, {"id": "d8ae4ac3-cba1-40ca-a463-707c04e26add", "type": "topic", "title": "PR History, Theory, Roles, and Professional Standards", "description": "This topic situates PR in its historical development, theoretical models, and contemporary professional responsibilities.", "children": [{"id": "bd51c7e2-d588-41d6-83b1-f06057d474a8", "type": "subtopic", "title": "History of PR", "children": [{"id": "a216bf1a-70b0-4b6b-82d7-c63ab234c89c", "type": "concept", "title": "Press agentry and public information"}, {"id": "becb188d-23f4-49cf-8288-c0b60efc5729", "type": "concept", "title": "Two-way asymmetrical and symmetrical models"}, {"id": "7515110c-0c63-427b-8cea-3b303a793a10", "type": "concept", "title": "Social movements, corporate PR, public affairs, and digital PR"}], "description": "Students see how PR developed through publicity, propaganda, advocacy, and professionalization."}, {"id": "d0983d33-60f8-4eae-a054-4631055e8e56", "type": "subtopic", "title": "PR theory", "children": [{"id": "34655021-3f7e-405b-8215-43406cccfe1b", "type": "concept", "title": "Excellence theory, relationship management, agenda-building, and framing"}, {"id": "4b3aec77-03fc-4593-a7cc-20aaf7672e7c", "type": "concept", "title": "Situational theory of publics"}, {"id": "112e0567-7a7b-4c41-98e9-52146f008e8a", "type": "concept", "title": "Dialogue, reputation, and stakeholder theory"}], "description": "Theories help explain why communication succeeds or fails."}, {"id": "9fe53603-9b17-45bc-ac8c-fc6df6d257d2", "type": "subtopic", "title": "Professional standards", "children": [{"id": "3ecf43df-504a-4c0e-9989-279b6ec11031", "type": "concept", "title": "PRSA and IABC standards"}, {"id": "276926a5-b68b-472f-897f-41c372cc2052", "type": "concept", "title": "Transparency, accuracy, loyalty, advocacy, and public interest"}, {"id": "3d917808-9cf7-4153-af10-1c41f0f0843c", "type": "concept", "title": "Professional conduct and continuing development"}], "description": "Students learn the norms that separate professional practice from manipulation."}]}, {"id": "1fa8ef91-1018-4182-b5d5-261779a40853", "type": "topic", "title": "Research, Situation Analysis, Communication Audits, and Formative Insight", "description": "Students learn to diagnose communication problems before proposing tactics.", "children": [{"id": "44dffe1e-fe48-4636-b2a3-3b8b8ba10773", "type": "subtopic", "title": "Situation analysis", "children": [{"id": "f66f0f72-3a62-4f4b-aea2-7114765c34c8", "type": "concept", "title": "SWOT, PESTLE, background research, and issue history"}, {"id": "6f0fd443-4a02-4c40-9809-6b6f0d9ac666", "type": "concept", "title": "Organizational goals and communication gaps"}, {"id": "2a4a4c4c-f6cf-4382-8e4d-1196afb629b7", "type": "concept", "title": "Constraints, risks, assumptions, and opportunities"}], "description": "Students learn to define the problem before designing solutions."}, {"id": "f2ba6198-a6b7-43fc-84c3-c9f241c4404c", "type": "subtopic", "title": "Research methods", "children": [{"id": "78c67954-2f17-4120-a018-066a66c855b0", "type": "concept", "title": "Interviews, focus groups, surveys, content analysis, social listening, and media monitoring"}, {"id": "68ac5508-cd02-4242-a5b1-73bfd0246259", "type": "concept", "title": "Secondary research and benchmarking"}, {"id": "3243a390-4d80-44fb-b2ae-887cd735244c", "type": "concept", "title": "Validity, bias, sampling, and ethics"}], "description": "The gist is to gather evidence from more than one source."}, {"id": "c0da03a7-7a7d-42d3-8d86-f12986658673", "type": "subtopic", "title": "Communication audits", "children": [{"id": "ef99b0d0-c8bc-4c8d-bfc1-41a0576b7e7e", "type": "concept", "title": "Channel inventory and message review"}, {"id": "4afa50bd-dcd3-49a5-b3c8-3d8db27d0fb4", "type": "concept", "title": "Stakeholder feedback and internal communication analysis"}, {"id": "f9922419-c67d-4606-b1d3-7db645af73a1", "type": "concept", "title": "Insight statements and research implications"}], "description": "Audits reveal what messages, channels, and relationships already exist."}]}, {"id": "70fd16c8-152b-4a32-a7db-00cf5033575a", "type": "topic", "title": "Stakeholder Publics, Audience Segmentation, Relationship Management, and Community Engagement", "description": "This module teaches students to identify publics, understand their needs, and build durable relationships.", "children": [{"id": "3e7e8d54-630e-433b-a8ab-3bd7e85c071a", "type": "subtopic", "title": "Stakeholder mapping", "children": [{"id": "ab6f7d8d-fb9b-4e25-a3ce-2d2709ea1605", "type": "concept", "title": "Internal, external, primary, secondary, active, latent, and aware publics"}, {"id": "dac2f6a2-f43f-493a-981f-67190d81816f", "type": "concept", "title": "Power, interest, legitimacy, urgency, and influence"}, {"id": "de566b60-0a1b-4041-b445-aa031bd1fae4", "type": "concept", "title": "Stakeholder maps and priority decisions"}], "description": "Students learn who matters, why they matter, and what they need."}, {"id": "67780724-a3e7-417a-8b63-5395f37e9282", "type": "subtopic", "title": "Segmentation and personas", "children": [{"id": "f22233e2-0ffa-482d-990f-9916f2c4e048", "type": "concept", "title": "Demographics, psychographics, behaviors, needs, and media habits"}, {"id": "a5760d7b-766f-444c-b198-19d7f15938e9", "type": "concept", "title": "Personas, empathy maps, and journey maps"}, {"id": "8351ec65-fb9e-4342-ba9e-8ca0f455aec4", "type": "concept", "title": "Avoiding stereotypes and deficit assumptions"}], "description": "Segmentation makes strategy specific and actionable."}, {"id": "e30bf4c9-ab65-4326-8dd8-98a0a361fe36", "type": "subtopic", "title": "Community engagement", "children": [{"id": "c1325c2e-84e9-432f-9c12-91827ce08fab", "type": "concept", "title": "Community partnerships and coalition-building"}, {"id": "5551a6f9-226d-47fe-81fd-e7feb1c874dd", "type": "concept", "title": "Listening sessions, advisory groups, and public meetings"}, {"id": "f53195e2-38fb-4f19-ad8f-705413f0ba0b", "type": "concept", "title": "Trust, reciprocity, and accountability"}], "description": "PR becomes stronger when it listens before it speaks."}]}, {"id": "0e61c5c3-adbf-43fc-8458-d628ba615152", "type": "topic", "title": "Strategic Communication Planning: RPIE, Goals, Objectives, Strategies, and Tactics", "description": "Students build complete strategic plans using research, planning, implementation, and evaluation.", "children": [{"id": "977c6f79-7c40-4790-be9c-0d0e79e095f4", "type": "subtopic", "title": "RPIE process", "children": [{"id": "7c5b6576-1ae3-4831-9734-3b7911724ba6", "type": "concept", "title": "Research inputs and problem statements"}, {"id": "2b8e97c5-5af6-4433-8781-3d827b5a95dd", "type": "concept", "title": "Planning logic and implementation choices"}, {"id": "6e839c5f-6085-4249-99a3-0948dc0719a9", "type": "concept", "title": "Evaluation built in from the beginning"}], "description": "Students use research, planning, implementation, and evaluation as the professional planning backbone."}, {"id": "b0642926-edc3-47ef-b0f6-4c68d0aa363c", "type": "subtopic", "title": "Goals and objectives", "children": [{"id": "9d96ecc9-e395-4f7d-a604-9810ded153e5", "type": "concept", "title": "Informational, attitudinal, behavioral, and relational objectives"}, {"id": "6e14f7a2-a6fa-4f6c-a043-e31091781d97", "type": "concept", "title": "SMART objectives and logic models"}, {"id": "95f1e241-5e65-4d9b-970a-15efd51b8097", "type": "concept", "title": "Outputs, outtakes, outcomes, and impact"}], "description": "Clear objectives make communication measurable and manageable."}, {"id": "294ca68c-0c43-4219-8f3a-932491a8e7fa", "type": "subtopic", "title": "Strategies and tactics", "children": [{"id": "52c49111-aae5-4ad9-85fc-73418240bcbb", "type": "concept", "title": "Strategy statements and rationale"}, {"id": "9dc148b2-2613-45ab-9c8d-09cb4d3c537e", "type": "concept", "title": "Tactics, owners, timelines, and budgets"}, {"id": "00636320-74f7-4237-84de-7de5f7335924", "type": "concept", "title": "Feasibility, sequencing, and contingency planning"}], "description": "Students learn the difference between broad strategic direction and concrete actions."}]}, {"id": "76102f64-e9b6-4254-bcc8-86858254f315", "type": "topic", "title": "Message Strategy, Positioning, Persuasion, and Proof", "description": "This topic translates research into clear, credible, ethical messages and reasons to believe.", "children": [{"id": "be5ed317-a2e6-41ae-8db3-937481cdeac4", "type": "subtopic", "title": "Message architecture", "children": [{"id": "95cf02a8-5a6e-496b-90b6-57a722a9a2d3", "type": "concept", "title": "Core message, message pillars, proof points, and calls to action"}, {"id": "069496b6-559b-461f-9bb5-c2917112ad5f", "type": "concept", "title": "Audience-specific message matrices"}, {"id": "4a528504-4a74-4fd6-9d25-c3fffc2c8e7d", "type": "concept", "title": "Boilerplates, talking points, and Q&A documents"}], "description": "Students organize communication into a clear hierarchy."}, {"id": "81aa9c8a-9a6c-4dff-81ff-b240e6cd4782", "type": "subtopic", "title": "Positioning and persuasion", "children": [{"id": "697f49c5-e45f-4394-80b5-003cc98b9e32", "type": "concept", "title": "Audience insight, value proposition, and differentiation"}, {"id": "5304a950-fcb8-41f2-9d90-17362935678c", "type": "concept", "title": "Framing, emotion, social proof, and narrative"}, {"id": "dd143585-acfd-407d-9eab-fe44b234ac5e", "type": "concept", "title": "Persuasion without manipulation"}], "description": "Messages must make a credible, memorable, and ethical case."}, {"id": "952e0a21-d92f-4f75-b37b-6df7d2c0ed5f", "type": "subtopic", "title": "Evidence and proof", "children": [{"id": "8ef30261-53a1-4eee-b804-477588ce8bc8", "type": "concept", "title": "Data, testimonials, case examples, third-party validation, and visuals"}, {"id": "ecf37109-f2ab-4f09-9460-2cd41afa642e", "type": "concept", "title": "Claim checking and source attribution"}, {"id": "98891336-64d1-4027-97da-0305248fefb6", "type": "concept", "title": "Plain language and uncertainty language"}], "description": "Good PR messages are supported by facts, examples, and credible sources."}]}, {"id": "d0de7943-6936-4987-9b22-2b80bbee6978", "type": "topic", "title": "PR Writing: News Releases, Fact Sheets, Briefs, Pitches, Speeches, and Digital Copy", "description": "Students practice professional writing across PR, media, organizational, web, and social contexts.", "children": [{"id": "6207f6eb-a968-4e0a-9fb1-6ed97368258d", "type": "subtopic", "title": "Core PR genres", "children": [{"id": "44ad4246-f17e-4e1c-a967-d867f9e0afa9", "type": "concept", "title": "News releases, media advisories, fact sheets, backgrounders, and executive briefs"}, {"id": "b7acece3-13ab-4b79-bef6-5034ed882ac6", "type": "concept", "title": "Pitches, bios, speeches, op-eds, newsletters, and FAQs"}, {"id": "79f532c3-d15f-4264-bcb4-25673997fdad", "type": "concept", "title": "AP style, headlines, leads, and editing"}], "description": "Students practice the writing formats that anchor PR work."}, {"id": "9187b9a4-70a6-4e58-9f12-e8a33dd38855", "type": "subtopic", "title": "Digital and social copy", "children": [{"id": "85946827-7ecc-4813-b9d1-46e5fece73b4", "type": "concept", "title": "Web copy, email, captions, posts, threads, and landing pages"}, {"id": "3b99f2cc-3c93-4c11-842e-cb30d9265847", "type": "concept", "title": "Voice, tone, accessibility, and calls to action"}, {"id": "991ac2d2-e42d-4bae-9676-f179c1eeb074", "type": "concept", "title": "Search, scannability, and link strategy"}], "description": "Writing must adapt to web, email, mobile, and platform constraints."}, {"id": "ef4b2e92-a49b-41d0-b6f3-c3ed21c99b10", "type": "subtopic", "title": "Editorial workflow", "children": [{"id": "e64c81bb-9a11-4e6a-aada-0930967f1e96", "type": "concept", "title": "Drafting, editing, approvals, and style guides"}, {"id": "d83e9220-92be-416b-8929-0b2f7790e223", "type": "concept", "title": "Inclusive language and plain language"}, {"id": "f2b224f5-5cca-4436-bff2-c735a420a63c", "type": "concept", "title": "Portfolio-ready writing samples"}], "description": "Professional writing requires revision, review, and version control."}]}, {"id": "b21d5d5e-37ad-4782-91dd-78cfd3d93384", "type": "topic", "title": "Media Relations, Journalist Outreach, Spokesperson Preparation, and Briefings", "description": "This module develops media-facing skills for pitching, interviews, briefings, and reputation-building.", "children": [{"id": "fa9fd824-6794-460c-bc53-043adab690d3", "type": "subtopic", "title": "Media landscape", "children": [{"id": "50940c06-72df-4bf2-92ef-fca9f94b1351", "type": "concept", "title": "Beats, deadlines, editorial priorities, and newsroom pressures"}, {"id": "f665d064-65e6-417d-955c-3406efec33c0", "type": "concept", "title": "Earned media, exclusives, embargoes, and background briefings"}, {"id": "46fdb206-441e-4aa5-b453-5e2f9c5a2273", "type": "concept", "title": "Local, trade, national, and digital-native media"}], "description": "Students learn how journalists work and what makes information newsworthy."}, {"id": "f891230a-6517-410f-addb-3af5271a6764", "type": "subtopic", "title": "Pitching and outreach", "children": [{"id": "cd748ebf-aa20-4e87-ba4b-774b77582b71", "type": "concept", "title": "Media lists, tailored pitches, follow-up, and relationship-building"}, {"id": "687834fe-9546-46b6-955e-01c05523c087", "type": "concept", "title": "Newsworthiness, subject lines, and source preparation"}, {"id": "d2af339f-c4ac-457d-b54b-d0d330eba178", "type": "concept", "title": "Ethics of access, spin, and pressure"}], "description": "A strong pitch respects journalist needs and audience relevance."}, {"id": "797b2b3f-07e3-41dd-9749-e0445e82e829", "type": "subtopic", "title": "Spokesperson preparation", "children": [{"id": "f9d20df7-28aa-4c8c-b810-9aa6623ae36a", "type": "concept", "title": "Message discipline, bridging, flagging, and plain language"}, {"id": "857bb65d-3de1-4626-8004-e0a6da33623f", "type": "concept", "title": "Mock interviews and hard questions"}, {"id": "85f87190-fa52-4458-93e4-0b6015090d67", "type": "concept", "title": "Briefing materials and post-interview follow-up"}], "description": "Students prepare people to communicate clearly under scrutiny."}]}, {"id": "e090f6b7-c4c4-4517-8bd5-d8ca4de07c43", "type": "topic", "title": "PESO, Integrated Communication, Content Strategy, Events, Sponsorship, and Campaign Execution", "description": "Students learn to coordinate paid, earned, shared, and owned media into coherent campaigns.", "children": [{"id": "0fb2dbdc-685b-4e80-8364-b188a861901e", "type": "subtopic", "title": "PESO model", "children": [{"id": "6c59c09a-442e-4b54-88bf-5213f5f1ebd9", "type": "concept", "title": "Paid ads, earned media, shared social, and owned web/email/content"}, {"id": "ff4ea7f9-5e27-41fd-9b1b-c4a71e5eb05f", "type": "concept", "title": "Channel mix and integrated message flow"}, {"id": "c7fc8809-5bb5-4f90-8da1-aa984ceef97c", "type": "concept", "title": "Avoiding siloed tactics"}], "description": "Students coordinate paid, earned, shared, and owned media roles."}, {"id": "cb63efde-f015-463d-a69c-55337b1adfb6", "type": "subtopic", "title": "Content and editorial planning", "children": [{"id": "05d92b4d-5bc3-422d-afff-e2f2f6001326", "type": "concept", "title": "Content pillars, calendars, governance, and production workflow"}, {"id": "88312f5c-bc7e-4829-9387-de0ad83d1f15", "type": "concept", "title": "Visual storytelling, video, newsletters, and blogs"}, {"id": "00a88d3a-b44c-4954-ab12-1e158dde35cd", "type": "concept", "title": "Events, webinars, sponsorship, and experiential communication"}], "description": "Campaigns need sustained content systems."}, {"id": "eff00d56-6df3-45b9-a4aa-dbc710466aa6", "type": "subtopic", "title": "Implementation management", "children": [{"id": "f3f24da4-709a-474c-bea3-d05a66c8d808", "type": "concept", "title": "Budgets, timelines, vendors, teams, and approvals"}, {"id": "ce84a255-9d16-488b-93b0-a99c4b3f5414", "type": "concept", "title": "Risk management and contingency planning"}, {"id": "72b9577f-cf6d-41f8-a958-71ba856a6638", "type": "concept", "title": "Launch, optimization, and reporting rhythms"}], "description": "Students learn how campaigns actually get delivered."}]}, {"id": "dfbcee73-6dbf-4d04-b0cf-ee0dacaccb72", "type": "topic", "title": "Digital and Social Media Strategy, Influencers, Community Management, and Platform Risk", "description": "This topic applies strategic communication to platform dynamics, creators, analytics, moderation, and online risk.", "children": [{"id": "5005effb-2836-4767-bc68-75b9c63e1d3e", "type": "subtopic", "title": "Platform strategy", "children": [{"id": "1ad283f7-77a1-4fce-9c0e-1abd8b1c75cb", "type": "concept", "title": "Platform norms, algorithms, formats, and distribution"}, {"id": "12717c2a-606f-421a-b239-00df3696a8ac", "type": "concept", "title": "Search, discoverability, and social listening"}, {"id": "601d5c91-ddfd-4ee1-b753-c2c524ce1976", "type": "concept", "title": "Paid amplification and organic reach"}], "description": "Students choose digital channels by audience, affordance, and objective."}, {"id": "0655182f-ca4c-4dab-9ee0-087735a864b4", "type": "subtopic", "title": "Influencers and creators", "children": [{"id": "4ab9e0db-5cba-4ae2-bee0-71b46be0e700", "type": "concept", "title": "Creator fit, briefs, contracts, disclosure, and FTC rules"}, {"id": "fc66c70c-42fe-4fc8-aa35-c4c2e3c477c8", "type": "concept", "title": "Authenticity, audience trust, and co-creation"}, {"id": "e2e7682f-13df-46b9-bd2a-e34553f0edc4", "type": "concept", "title": "Monitoring and reputation risk"}], "description": "Creator partnerships can expand trust or create risk."}, {"id": "80af193a-1f5a-4751-b454-c7cf7733bc34", "type": "subtopic", "title": "Community management", "children": [{"id": "d3a65300-0207-43a7-95db-3f3d963a4e9d", "type": "concept", "title": "Social care, comment policy, and moderation"}, {"id": "94756706-49dd-406b-95df-4a4b5272db32", "type": "concept", "title": "Online risk, harassment, misinformation, and escalation"}, {"id": "60627708-634c-4a7f-ae9e-4cc57da943c8", "type": "concept", "title": "Analytics, dashboards, and community insight"}], "description": "Students learn to listen, respond, moderate, and escalate."}]}, {"id": "bc153e4d-159e-4616-8f87-c017c8ce747d", "type": "topic", "title": "Reputation, Brand, Trust, Corporate Social Responsibility, and Issues Management", "description": "Students examine how organizations build, protect, and repair legitimacy and trust.", "children": [{"id": "1bc5ff0e-5093-47b1-98a8-a83f1fe569a4", "type": "subtopic", "title": "Reputation and trust", "children": [{"id": "815fefb9-163a-46fe-9c59-d8f170440cc2", "type": "concept", "title": "Legitimacy, credibility, competence, care, and integrity"}, {"id": "ebad459c-89ea-47dd-bee5-159e6a4c46ba", "type": "concept", "title": "Reputation audits and trust drivers"}, {"id": "3aa03072-ca47-4992-aafd-a54e7d20cb7d", "type": "concept", "title": "Brand-reputation connections"}], "description": "Reputation is built through behavior, communication, and stakeholder memory."}, {"id": "82c948aa-86a2-429d-8968-a416c628d20e", "type": "subtopic", "title": "CSR and purpose", "children": [{"id": "d0bde2fb-2b16-4aa0-ae08-cc35c1914650", "type": "concept", "title": "CSR, ESG, social impact, and community investment"}, {"id": "e8a7ff5c-49b3-4a18-94b0-aa339d82f5cf", "type": "concept", "title": "Purpose washing, greenwashing, and stakeholder skepticism"}, {"id": "aef7687f-64f9-42d6-931d-6d104bc2b534", "type": "concept", "title": "Impact proof and progress communication"}], "description": "Students evaluate purpose claims through evidence and accountability."}, {"id": "214a5bed-fddd-4926-8a57-1a5d97492f0b", "type": "subtopic", "title": "Issues management", "children": [{"id": "af617aff-ad5f-4d95-a674-fd073b96097c", "type": "concept", "title": "Environmental scanning, public affairs, and issue lifecycle"}, {"id": "2933d64f-3ed5-46e0-99c7-c566eb1a8012", "type": "concept", "title": "Risk assessment and stakeholder concern mapping"}, {"id": "09383fb6-8b08-4cc2-9bb3-5a8fc9170a8d", "type": "concept", "title": "Position statements and leadership counsel"}], "description": "Organizations need to anticipate contested issues before crisis arrives."}]}, {"id": "96dd5117-6f17-423e-83a8-fa2acdf1998d", "type": "topic", "title": "Crisis Communication, Risk Communication, Apology, Recovery, and After-Action Learning", "description": "This module prepares students to communicate under pressure with accuracy, care, and accountability.", "children": [{"id": "9879aa46-a09c-4802-9e4d-917f1607a9ff", "type": "subtopic", "title": "Crisis preparedness", "children": [{"id": "e8c2cfcb-92cc-4595-8193-91c114a05730", "type": "concept", "title": "Crisis types, stages, warning signals, and vulnerability audits"}, {"id": "b0b309ac-3192-4345-afe8-164d2e7b6eff", "type": "concept", "title": "Crisis team roles and command structures"}, {"id": "0c0ff141-48f1-4990-8f66-9027b7861923", "type": "concept", "title": "Message maps, holding statements, and escalation workflows"}], "description": "Students learn the tools needed before pressure arrives."}, {"id": "97449b4b-6a84-44a3-99ee-f356a9c9b02d", "type": "subtopic", "title": "Crisis response", "children": [{"id": "32d0973e-f733-48f9-a632-9cf4ff946cf0", "type": "concept", "title": "Stakeholder care, internal communication, and media briefings"}, {"id": "a55db047-4379-42b8-b469-f572983e31d8", "type": "concept", "title": "Social media escalation and rumor control"}, {"id": "15ae49b0-3650-4b23-bd74-cf0a68aabf53", "type": "concept", "title": "Apology, correction, and legal coordination"}], "description": "Strong response prioritizes affected people, facts, and accountability."}, {"id": "34922250-498c-42a5-88ae-34a80619a4b7", "type": "subtopic", "title": "Recovery and learning", "children": [{"id": "10059ed1-65a9-43f3-8aae-5f0f5747a004", "type": "concept", "title": "After-action review and response evaluation"}, {"id": "635bd769-daa1-4796-a362-07a4dd0c5449", "type": "concept", "title": "Reputation repair and corrective action"}, {"id": "6b62c41f-89fb-4922-9fd0-e6054e26ee14", "type": "concept", "title": "Long-term stakeholder follow-up"}], "description": "Crisis work continues after the immediate news cycle."}]}, {"id": "1733a7b3-052d-45d7-9461-dc759500fadb", "type": "topic", "title": "Internal, Employee, Executive, Nonprofit, Government, and Global PR Contexts", "description": "Students compare PR practice across organizational settings, sectors, and cultures.", "children": [{"id": "e5f9971c-c35c-4cdb-8e70-19aaf4584354", "type": "subtopic", "title": "Internal and employee communication", "children": [{"id": "09b3db00-3d50-40f6-8a9c-87b10c1e78c2", "type": "concept", "title": "Manager toolkits, town halls, intranet, and employee advocacy"}, {"id": "6c90d408-1a1e-4c4c-b831-c39db2727028", "type": "concept", "title": "Change communication and culture alignment"}, {"id": "ee88e1a1-7d15-44ff-8dc4-52630d845dc0", "type": "concept", "title": "Trust, transparency, and feedback loops"}], "description": "Employees are publics, messengers, and culture carriers."}, {"id": "7e9a4002-5ea9-4e67-be59-8e88e5a4e5c2", "type": "subtopic", "title": "Sector contexts", "children": [{"id": "cde0d775-47b0-4d69-8d00-ac3bcdc248f0", "type": "concept", "title": "Corporate, nonprofit, government, education, health, and agency contexts"}, {"id": "d6a9ac42-5edc-4df0-8c5b-44c2ae537439", "type": "concept", "title": "Public affairs, advocacy, fundraising, and donor communication"}, {"id": "47c733e1-2d98-444e-93ee-4c87f3807ef9", "type": "concept", "title": "Regulatory and public-record constraints"}], "description": "PR practice changes across sector and mission."}, {"id": "0c7ed968-2c24-47aa-9b0e-7f844148ddb0", "type": "subtopic", "title": "Global and intercultural PR", "children": [{"id": "efb13a84-3bf7-4373-9f14-29f79386ad3b", "type": "concept", "title": "Localization, transcreation, and global consistency"}, {"id": "444778b2-8685-4c17-b35d-538103be0222", "type": "concept", "title": "Intercultural competence and ethical representation"}, {"id": "3895d79a-a130-408f-8467-84842d04fa40", "type": "concept", "title": "Global media, publics, and reputation risk"}], "description": "Strategic communication must adapt across cultures and markets."}]}, {"id": "2e55cb5e-3c29-4648-9ba7-3ab12635fc31", "type": "topic", "title": "Ethics, Law, DEI, Accessibility, Privacy, AI, and Responsible Advocacy", "description": "This topic builds judgment for persuasive communication that is truthful, inclusive, legal, and accountable.", "children": [{"id": "a56b86a1-eb29-4c61-bd74-d1971dbb0048", "type": "subtopic", "title": "Ethical advocacy", "children": [{"id": "6efd9211-2675-4101-b438-f658aad12fee", "type": "concept", "title": "Accuracy, transparency, disclosure, and conflicts of interest"}, {"id": "41779fac-b634-40f4-9a04-c969703dc22f", "type": "concept", "title": "Astroturfing, manipulation, and deception"}, {"id": "bd390be2-c4b4-48b8-a075-dd7ed189db8d", "type": "concept", "title": "PRSA Code of Ethics and case analysis"}], "description": "Students learn to advocate while protecting truth and public trust."}, {"id": "5462ed17-1700-4b76-8c95-1cd5d83f0bd8", "type": "subtopic", "title": "Law and policy", "children": [{"id": "41a6759a-0969-426f-885c-cc4e84a4242b", "type": "concept", "title": "Defamation, privacy, copyright, fair use, and commercial speech"}, {"id": "a0def938-8fce-4390-80ae-5c257a5a85dc", "type": "concept", "title": "FTC endorsements, native advertising, lobbying, and disclosure"}, {"id": "503abf31-4a41-4cf9-81cc-d691679d51ca", "type": "concept", "title": "Data protection, platform rules, and records"}], "description": "PR work operates within legal and regulatory boundaries."}, {"id": "9ff5f599-970d-430d-a16c-e4d796b7b601", "type": "subtopic", "title": "Responsible innovation", "children": [{"id": "f5bef196-c2ca-4711-8c2c-d65a33ef3d3a", "type": "concept", "title": "DEI, inclusive language, accessibility, and multilingual communication"}, {"id": "09d78375-b605-4532-9696-a1b0604c6d6d", "type": "concept", "title": "AI drafting, monitoring, bias, hallucination, and human review"}, {"id": "0f592aea-84e3-4648-a296-5dbba10001f6", "type": "concept", "title": "Synthetic media, provenance, and trust"}], "description": "Modern PR must address inclusion, accessibility, and AI responsibly."}]}, {"id": "e4153a47-7c4e-419f-aef4-a2377da4f02f", "type": "topic", "title": "Measurement, Evaluation, Dashboards, Campaign Case Study, and Capstone Portfolio", "description": "Students evaluate communication results and synthesize the course in a professional campaign portfolio.", "children": [{"id": "41f670d1-5fe7-4340-9d2b-98f361b00a88", "type": "subtopic", "title": "Measurement frameworks", "children": [{"id": "fd8f0681-488a-436f-9cf5-2956c4017153", "type": "concept", "title": "AMEC framework, logic models, and KPI trees"}, {"id": "87b0d4eb-4590-4c1e-a19b-fe9d47a000b7", "type": "concept", "title": "Outputs, outtakes, outcomes, and impact"}, {"id": "166b6022-e8fc-44b8-8fd6-74bddcfaf8b4", "type": "concept", "title": "Awareness, sentiment, trust, behavior, and relationships"}], "description": "Students connect evaluation to objectives and stakeholder outcomes."}, {"id": "99749f38-1b8f-4a05-bc27-cf8ace57f6c2", "type": "subtopic", "title": "Analytics and reporting", "children": [{"id": "f9944c05-5741-4dbd-b9ad-ae5afe156eb5", "type": "concept", "title": "Media monitoring, share of voice, web analytics, social analytics, and surveys"}, {"id": "2313e106-7521-43aa-adfb-1ca473097983", "type": "concept", "title": "Dashboards, data visualization, and executive summaries"}, {"id": "9e1185c8-80e2-493d-85a8-127f4973b669", "type": "concept", "title": "Attribution limits and ethical data use"}], "description": "Communication data becomes valuable when turned into decisions."}, {"id": "eea3224b-06d0-43fc-8175-f5d1965f0a84", "type": "subtopic", "title": "Capstone portfolio", "children": [{"id": "ff5837be-7e89-4b30-bc00-3d62d2dfc4ed", "type": "concept", "title": "Research brief, strategic plan, message framework, writing samples, and PESO plan"}, {"id": "96f34b35-67c0-4264-a7b2-df8ee0a5f90c", "type": "concept", "title": "Measurement plan, ethics review, and crisis contingency"}, {"id": "2d11f778-f528-4e72-b507-a61be74ba3b8", "type": "concept", "title": "Final presentation, critique, and revision"}], "description": "Students synthesize the course in a professional campaign package."}]}], "dbBacked": true}$prscjson$::jsonb,
